/* MIDNA Nails (Konzept) · Hero: ветер в волосах (WebGL), основа — шаблон.
   v2: точная маска (двигаются только волосы, лицо/глаза/губы/серьга неподвижны), ветер сильнее и с направлением слева. Картинки встроены как data-URI,
   чтобы эффект работал и при открытии index.html прямо с диска (file://).
   Без WebGL или при prefers-reduced-motion остаётся обычный фон .hero .bg */
(function(){
  var IMG="data:image/jpeg;base64,";
  var MASK="data:image/png;base64,";
  var AMP=0.024;    // сила ветра (доля ширины фото); 0.016 — тише, 0.032 — сильнее
  var POS_Y=0.30;   // как в CSS: background-position center 30%

  if(window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  var host=document.querySelector('.hero .bg'); if(!host) return;
  var cv=document.createElement('canvas');
  cv.setAttribute('aria-hidden','true');
  cv.style.cssText='position:absolute;inset:0;width:100%;height:100%;display:block;opacity:0;transition:opacity .8s';
  var gl=cv.getContext('webgl',{alpha:true,premultipliedAlpha:false,antialias:false});
  if(!gl) return;

  var vs='attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';
  var fs=[
  'precision mediump float;',
  'uniform sampler2D img,msk;uniform vec2 res;uniform float t,amp,posY;',
  'float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}',
  'float n(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);',
  ' return mix(mix(h(i),h(i+vec2(1,0)),f.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),f.x),f.y);}',
  'void main(){',
  ' vec2 fc=vec2(gl_FragCoord.x,res.y-gl_FragCoord.y);',
  ' float s=max(res.x,res.y);',           // квадратное фото, cover
  ' vec2 off=vec2((res.x-s)*.5,(res.y-s)*posY);',
  ' vec2 uv=(fc-off)/s;',
  ' float m=texture2D(msk,uv).r;',
  ' float gust=.65+.35*sin(t*.33)+.15*sin(t*.91+1.3);',
  ' vec2 q=uv*2.6;',
  ' float a=n(q+vec2(t*.22,t*.07))-.5;',
  ' float b=n(q*2.4+vec2(-t*.35,t*.18)+7.3)-.5;',
  ' float w=sin(t*1.1+uv.y*6.+uv.x*3.)*.35;',
  ' float flow=sin(uv.y*9.-t*2.1+a*3.)*.45+sin(uv.y*17.-t*3.4+uv.x*4.)*.18;',   // пряди «текут» по ветру
  ' vec2 d=vec2(a+w*.6+b*.5+flow+.25*gust,(b-a)*.55+w*.25+flow*.35)*amp*gust*m;',
  ' gl_FragColor=texture2D(img,clamp(uv+d,0.,1.));',
  '}'].join('\n');
  function sh(type,src){var o=gl.createShader(type);gl.shaderSource(o,src);gl.compileShader(o);return o;}
  var pr=gl.createProgram();
  gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs));
  gl.linkProgram(pr); if(!gl.getProgramParameter(pr,gl.LINK_STATUS)) return;
  gl.useProgram(pr);
  var buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);
  gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
  var lp=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(lp);gl.vertexAttribPointer(lp,2,gl.FLOAT,false,0,0);
  var U={};['img','msk','res','t','amp','posY'].forEach(function(k){U[k]=gl.getUniformLocation(pr,k);});
  gl.uniform1i(U.img,0);gl.uniform1i(U.msk,1);gl.uniform1f(U.amp,AMP);gl.uniform1f(U.posY,POS_Y);

  function tex(unit,src,cb){var im=new Image();im.onload=function(){
    var tx=gl.createTexture();gl.activeTexture(gl.TEXTURE0+unit);gl.bindTexture(gl.TEXTURE_2D,tx);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,im);cb();};im.src=src;}

  function size(){var r=host.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);
    var w=Math.max(1,Math.round(r.width*dpr)),h=Math.max(1,Math.round(r.height*dpr));
    if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;gl.viewport(0,0,w,h);}
    gl.uniform2f(U.res,w,h);}

  var visible=true,raf=0,t0=performance.now();
  function frame(now){raf=0;if(!visible||document.hidden)return;
    gl.uniform1f(U.t,(now-t0)/1000);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);raf=requestAnimationFrame(frame);}
  function go(){if(!raf&&visible&&!document.hidden)raf=requestAnimationFrame(frame);}

  var left=2;function ready(){if(--left)return;
    host.appendChild(cv);size();gl.uniform1f(U.t,0);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
    requestAnimationFrame(function(){cv.style.opacity='1';});
    if(window.ResizeObserver)new ResizeObserver(size).observe(host);else addEventListener('resize',size);
    if(window.IntersectionObserver)new IntersectionObserver(function(e){visible=e[0].isIntersecting;go();}).observe(host);
    document.addEventListener('visibilitychange',go);go();}
  tex(0,IMG,ready);tex(1,MASK,ready);
})();
